import AVFoundation

/// The video pump of a row a bundled encoder writes (`settings.writer`, spec §11 CX-12):
/// the composed frames converted to I010 on the export's video queue and encoded by SVT-AV1
/// on a serial encode queue of its own, whose packets go to a passthrough
/// `AVAssetWriterInput` as `av01` samples.
///
/// **Two queues, one owner each.** The video queue reads, converts and hands each frame on,
/// bounded to three in flight (`slots`) so a slow encoder holds the read back; the encode
/// queue owns the encoder and the input — every `send`, every packet, every append, the
/// flush and `markAsFinished`. Progress is counted by frames SUBMITTED (the encoder's lag
/// is under a second); a cancel is the writer's flag, read before each read, each send and
/// each wait for the input.
///
/// **The finish** runs once on the encode queue, after every frame queued before it: at the
/// end of a clean read, the end of stream and a drain to the last packet; on a stop (a
/// cancel, a failed read, another pump's failure), the end of stream and a drain that
/// discards; after an encoder error, neither. Every exit marks the input finished and
/// leaves the group exactly once. The encoder itself is torn down by `close()`, after
/// `allInputsFinished`, as the reader is (G-17).
final class ExportEncodePump {
    /// The settings' `writer` this pump serves.
    static let writer = "svt_av1"

    let formatDescription: CMVideoFormatDescription

    private var encoder: SVTAV1Encoder?
    private let converter: ExportI010Converter
    private let encodeQueue = DispatchQueue(
        label: "com.kgalligan.framejob.export.encode", qos: .userInitiated)
    private let range: CMTimeRange
    private let frameDuration: CMTime
    private let slots = DispatchSemaphore(value: 3)

    // The encode queue's own state.
    private var times: [Int64: CMTime] = [:]
    private var lastTime = CMTime.negativeInfinity
    private var encoderFailed = false
    private var finished = false

    init(settings: ExportSettings, canvas: CGSize, range: CMTimeRange) throws {
        let frame = ExportWriter.encodedSize(settings)
        let speed = settings.encoderSpeed ?? .balanced
        let rate = settings.videoBitrate.map { max(1, $0) }
            ?? ExportWriter.defaultVideoBitrate(settings, bitsPerPixel: 0.07)
        let picture = ExportAV1Picture(color: settings.color)
        let encoder = try SVTAV1Encoder(
            width: frame.width, height: frame.height, fps: settings.fps, bitsPerSecond: rate,
            speed: speed, picture: picture)
        let config: ReelAV1.Config
        do {
            config = try ReelAV1.config(sequenceHeader: encoder.sequenceHeader)
        } catch {
            throw Exporter.ExportError.failed(
                "SVT-AV1's sequence header could not be read: \(error.localizedDescription)")
        }
        formatDescription = try ExportAV1Track.formatDescription(
            width: frame.width, height: frame.height, config: config, picture: picture)
        converter = try ExportI010Converter(
            width: frame.width, height: frame.height, canvas: canvas,
            fills: ExportWriter.fillsTheBox(settings, canvas: canvas), picture: picture, pool: 3)
        self.encoder = encoder
        self.range = range
        self.frameDuration = CompositionBuilder.frameDuration(settings.fps)
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("ExportEncodePump does not support NSCoder")
    }

    /// Reads `output` to its end on `queue` and encodes it into `input`; `group` is left once
    /// the input is finished. `readFailure` answers the reader's error when the read failed;
    /// `fail` records the first failure; `advance` is each submitted frame's file time.
    func run(
        input: AVAssetWriterInput, output: AVAssetReaderOutput, on queue: DispatchQueue,
        group: DispatchGroup, isStopping: @escaping () -> Bool,
        readFailure: @escaping () -> (any Error)?, fail: @escaping (any Error) -> Void,
        advance: @escaping (CMTime) -> Void
    ) {
        group.enter()
        let finish: (Bool) -> Void = { [self] clean in
            encodeQueue.async {
                self.finish(
                    clean: clean, input: input, group: group, isStopping: isStopping, fail: fail)
            }
        }
        queue.async { [self] in
            var index: Int64 = 0
            while true {
                guard !isStopping() else { return finish(false) }
                guard let sample = output.copyNextSampleBuffer() else {
                    // Dry: the range is read, or the read failed — never a branded, done
                    // file after a failed read.
                    if let error = readFailure() {
                        fail(error)
                        return finish(false)
                    }
                    return finish(true)
                }
                let time = CMSampleBufferGetPresentationTimeStamp(sample) - range.start
                guard time.isNumeric, time >= .zero else { continue }
                slots.wait()
                guard let pixels = CMSampleBufferGetImageBuffer(sample),
                    let frame = converter.convert(pixels)
                else {
                    slots.signal()
                    fail(Exporter.ExportError.failed(
                        "A frame could not be prepared for the encoder."))
                    return finish(false)
                }
                let at = index
                index += 1
                encodeQueue.async {
                    self.encode(
                        frame, index: at, time: time, input: input, isStopping: isStopping,
                        fail: fail)
                }
                advance(time)
            }
        }
    }

    /// The encoder's teardown, on the encode queue, once every input is finished.
    func close() {
        encodeQueue.async { [self] in encoder = nil }
    }

    // MARK: - The encode queue

    private func encode(
        _ frame: I010Frame, index: Int64, time: CMTime, input: AVAssetWriterInput,
        isStopping: () -> Bool, fail: (any Error) -> Void
    ) {
        defer {
            converter.recycle(frame)
            slots.signal()
        }
        guard !finished, !encoderFailed, !isStopping(), let encoder else { return }
        do {
            try encoder.send(frame, index: index)
            times[index] = time
            while let packet = try encoder.nextPacket(wait: false) {
                guard write(packet, input: input, isStopping: isStopping, fail: fail) else {
                    return
                }
            }
        } catch {
            encoderFailed = true
            fail(error)
        }
    }

    /// One packet into the file: false once the export cannot go on.
    private func write(
        _ packet: SVTAV1Encoder.Packet, input: AVAssetWriterInput, isStopping: () -> Bool,
        fail: (any Error) -> Void
    ) -> Bool {
        guard !packet.data.isEmpty else { return true }
        var data = packet.data
        guard ReelAV1.stripTemporalDelimiters(&data) else {
            fail(Exporter.ExportError.failed("SVT-AV1 wrote a packet the core could not read."))
            return false
        }
        guard let time = times.removeValue(forKey: packet.pts), time > lastTime else {
            fail(Exporter.ExportError.failed("SVT-AV1 wrote a frame out of order."))
            return false
        }
        lastTime = time
        guard let sample = ExportAV1Track.sample(
            data, at: time, duration: frameDuration, format: formatDescription)
        else {
            fail(Exporter.ExportError.failed("An AV1 packet could not be made a sample."))
            return false
        }
        while !input.isReadyForMoreMediaData {
            guard !isStopping() else { return false }
            usleep(1000)
        }
        guard input.append(sample) else {
            fail(Exporter.ExportError.failed("The file could not be written."))
            return false
        }
        return true
    }

    /// The one exit: the end of stream and the drain as `clean` and the encoder allow, then
    /// the input finished and the group left, exactly once.
    private func finish(
        clean: Bool, input: AVAssetWriterInput, group: DispatchGroup, isStopping: () -> Bool,
        fail: (any Error) -> Void
    ) {
        guard !finished else { return }
        finished = true
        defer {
            input.markAsFinished()
            group.leave()
        }
        guard !encoderFailed, let encoder else { return }
        do {
            try encoder.sendEndOfStream()
            var writing = clean && !isStopping()
            while let packet = try encoder.nextPacket(wait: true) {
                if writing {
                    writing = write(packet, input: input, isStopping: isStopping, fail: fail)
                }
                if packet.isLast { break }
            }
        } catch {
            encoderFailed = true
            if clean { fail(error) }
        }
    }
}
import Foundation

/// SVT-AV1 v4.2.0, the `av1` row's encoder (spec §11 CX-2, CX-4, CX-12, CX-14): one handle
/// per export, configured once, fed video-range I010 pictures and drained of packets.
///
/// **Owned by one serial queue.** `ExportEncodePump`'s encode queue makes every call after
/// `init` — `send`, `sendEndOfStream`, `nextPacket` and the `deinit` — so the handle is
/// never touched from two threads; SVT runs its own worker threads behind it.
///
/// **The configuration** (CX-12 (2), (3); CX-13): the sheet's speed as SVT's preset (8, 6 or
/// 4), capped CRF — a constant quality matched to HEVC's at the cap, which is the settings'
/// rate or HEVC's 0.07 bits per pixel per frame — a closed GOP (`SVT_AV1_KF_REFRESH`) with a
/// keyframe at least every 2 s, 10-bit Main 4:2:0, and the picture's primaries, transfer
/// and matrix in video range written into the sequence header (CX-14 (4)): BT.709's for the
/// SDR picture, BT.2020 with HLG or PQ for the HDR ones. On PQ alone, HD-5's fixed mastering
/// display and content light level, which SVT writes as metadata OBUs on each KEY_FRAME
/// (CX-14 (5)).
final class SVTAV1Encoder {
    /// One packet as SVT answered it: its bytes (temporal delimiters still in), the `pts` the
    /// picture was sent with, and whether it is the last.
    struct Packet {
        let data: Data
        let pts: Int64
        let isLast: Bool
    }

    /// The sequence header OBU (`svt_av1_enc_stream_header`), the `av1C` record's source.
    let sequenceHeader: Data

    private var handle: UnsafeMutablePointer<EbComponentType>?
    /// Set after the first failed call: nothing more is asked of the handle but its teardown.
    private var broken = false

    init(
        width: Int, height: Int, fps: Fps, bitsPerSecond: Int, speed: EncoderSpeed,
        picture: ExportAV1Picture
    ) throws {
        _ = Self.installLogCallback
        var config = EbSvtAv1EncConfiguration()
        var opened: UnsafeMutablePointer<EbComponentType>?
        try Self.check(svt_av1_enc_init_handle(&opened, &config), "svt_av1_enc_init_handle")
        guard let opened else {
            throw Exporter.ExportError.failed("SVT-AV1 could not start: no handle was made.")
        }
        config.enc_mode = speed.svtPreset
        config.source_width = UInt32(clamping: width)
        config.source_height = UInt32(clamping: height)
        config.frame_rate_numerator = UInt32(clamping: fps.num)
        config.frame_rate_denominator = UInt32(clamping: fps.den)
        config.encoder_bit_depth = 10
        config.encoder_color_format = EB_YUV420
        config.profile = MAIN_PROFILE
        // Capped CRF (CX-13): what SVT's own `--crf` sets, and the cap as `max_bit_rate`.
        let cap = min(max(1, bitsPerSecond), Self.maxCap)
        config.rate_control_mode = UInt8(SVT_AV1_RC_MODE_CQP_OR_CRF.rawValue)
        config.aq_mode = 2
        config.qp = Self.crf(speed: speed, bitsPerPixel: Double(cap)
            / (Double(max(1, width * height)) * (fps.double > 0 ? fps.double : 30)))
        config.max_bit_rate = UInt32(cap)
        // SVT-AV1 v4.2.0's own default (`EbSvtAv1Enc.h`, `enc_settings.c`): a soft cap that
        // hard footage may exceed, the owner's "quality first" (CX-13 (1)).
        config.mbr_over_shoot_pct = 50
        // Closed GOP, and a keyframe at least every 2 s: the period is ⌊2·fps⌋ frames.
        config.intra_refresh_type = SVT_AV1_KF_REFRESH
        let perSecond = fps.den > 0 ? Double(fps.num) / Double(fps.den) : 30
        config.intra_period_length = Int32(max(1, (2 * perSecond).rounded(.down))) - 1
        config.color_primaries = picture.primaries
        config.transfer_characteristics = picture.transfer
        config.matrix_coefficients = picture.matrix
        config.color_range = EB_CR_STUDIO_RANGE
        do {
            if picture.carriesHDR10 {
                try Self.setHDR10(&config)
            }
            sequenceHeader = try Self.start(opened, &config)
        } catch {
            _ = svt_av1_enc_deinit(opened)
            _ = svt_av1_enc_deinit_handle(opened)
            throw error
        }

