    /// The JSON `rc_container_describe` answers (the header's keys).
    pub fn describe(&self) -> Value {
        let v = self.video.as_ref();
        let a = self.audio.as_ref();
        let copied = |t: &Timing, sizes: &[Frame]| -> (u64, u64) {
